"""
apply_day8.py  -  ONE FILE that upgrades your production-rag project to Day 8.

HOW TO USE (Windows CMD), from inside your production-rag folder:
    .venv\\Scripts\\activate
    python apply_day8.py

What it does:
  1. Backs up every file it is about to change into  _backup_before_day8\\
  2. Writes all Day 1-8 code, tests, scripts, evals and docs into this folder
  3. NEVER touches: .env, .venv, app\\storage, evals\\reports
  4. Runs  pip install -r requirements.txt
  5. Runs  python scripts\\verify_day8.py  (tests + a real streamed /ask call)

Also fixes: pytest.ini now excludes _backup_before_* folders from test
collection, so old backups from earlier days' installers won't cause
spurious rate-limit test failures (a real issue hit and fixed on Day 7).

Options:
    --no-install    skip pip install
    --no-verify     skip the verification run
    --offline       verification without a live streamed call (free)
    --force         run even if this does not look like a production-rag folder
"""

